// HID usage encoding for ZMK Studio.
//
// ZMK packs a key code into one 32-bit binding parameter
// (dt-bindings/zmk/hid_usage.h + modifiers.h at v0.3):
//
//   ZMK_HID_USAGE(page, id) = (page << 16) | id
//   APPLY_MODS(mods, code)  = (mods << 24) | code      e.g. LC(A), LS(N1)
//
// with the modifier byte MOD_LCTL 0x01, LSFT 0x02, LALT 0x04, LGUI 0x08,
// RCTL 0x10, RSFT 0x20, RALT 0x40, RGUI 0x80. Implicitly shifted names
// (EXCL = LS(N1)) carry their modifier bits in the table below.
//
// HID_USAGE_VALUES is generated by evaluating every #define in ZMK v0.3
// keys.h, for every canonical code in src/data/keycodes.ts (aliases resolve to
// the same value). Regenerate it if keycodes.ts changes.

import type { Mod } from '../model/types'
import { canonicalCode } from '../data/keycodes'

export const MOD_BITS: Record<Mod, number> = {
  LCTRL: 0x01, LSHIFT: 0x02, LALT: 0x04, LGUI: 0x08,
  RCTRL: 0x10, RSHIFT: 0x20, RALT: 0x40, RGUI: 0x80,
}

/** Mods in canonical (bit) order. */
const MODS_BY_BIT: Mod[] = ['LCTRL', 'LSHIFT', 'LALT', 'LGUI', 'RCTRL', 'RSHIFT', 'RALT', 'RGUI']

export const HID_PAGE_GENERIC_DESKTOP = 0x01
export const HID_PAGE_KEYBOARD = 0x07
export const HID_PAGE_CONSUMER = 0x0c

