const BY_VALUE = new Map<number, string>()
for (const [code, v] of Object.entries(HID_USAGE_VALUES)) if (!BY_VALUE.has(v)) BY_VALUE.set(v, code)

export function usagePage(value: number): number {
  return (value >>> 16) & 0xff
}
export function usageId(value: number): number {
  return value & 0xffff
}
export function modBits(value: number): number {
  return (value >>> 24) & 0xff
}

export function modsToBits(mods: readonly Mod[] | undefined): number {
  let b = 0
  for (const m of mods ?? []) b |= MOD_BITS[m]
  return b
}

export function bitsToMods(bits: number): Mod[] {
  return MODS_BY_BIT.filter((m) => bits & MOD_BITS[m])
}

/**
 * Encode a key code (canonical name or alias) plus explicit modifiers into the
 * 32-bit parameter &kp / &mt / &sk expect. Returns undefined for unknown codes.
 *   ('A', ['LCTRL']) -> 0x01070004, ('EXCL') -> 0x0207001e
 */
export function encodeKeyParam(code: string, mods?: readonly Mod[]): number | undefined {
  const v = HID_USAGE_VALUES[canonicalCode(code)]
  if (v === undefined) return undefined
  return ((modsToBits(mods) << 24) | v) >>> 0
}

/**
 * Decode a 32-bit key parameter into our { code, mods } form. Prefers a code
 * whose implicit modifiers match exactly (LS(N1) -> EXCL), and otherwise uses
 * the unmodified key plus explicit mods (LC(A) -> A + [LCTRL]). Implicitly
 * shifted codes are also used when more mods are present (LC(LS(N1)) -> EXCL + [LCTRL]).
 * Returns undefined when no catalog code has that page/id.
 */
export function decodeKeyParam(value: number): { code: string; mods: Mod[] } | undefined {
  value = value >>> 0
  const exact = BY_VALUE.get(value)
  if (exact) return { code: exact, mods: [] }
  const bits = modBits(value)
  const base = value & 0xffffff
  // keys.h only defines implicitly *left-shifted* codes (EXCL = LS(N1), ...).
  if (bits & MOD_BITS.LSHIFT) {
    const code = BY_VALUE.get(((MOD_BITS.LSHIFT << 24) | base) >>> 0)
    if (code) return { code, mods: bitsToMods(bits & ~MOD_BITS.LSHIFT) }
  }
  const code = BY_VALUE.get(base)
  if (!code) return undefined
  return { code, mods: bitsToMods(bits) }
}

/** ZMK's text form of a key parameter, e.g. "LC(A)", or a hex literal when unknown. */
export function formatKeyParam(value: number): string {
  const d = decodeKeyParam(value)
  if (!d) return '0x' + (value >>> 0).toString(16)
  const fns: Record<Mod, string> = { LCTRL: 'LC', LSHIFT: 'LS', LALT: 'LA', LGUI: 'LG', RCTRL: 'RC', RSHIFT: 'RS', RALT: 'RA', RGUI: 'RG' }
  let out = d.code
  for (let i = d.mods.length - 1; i >= 0; i--) out = `${fns[d.mods[i]]}(${out})`
  return out
}
